// AI Visibility prompt set: 8 unbranded buyer prompts generated by Claude from
// the AEO Playbook, plus one fixed brand prompt. Stored in audit_ai_prompts and
// reused on every run so scores compare like with like.

import Anthropic from '@anthropic-ai/sdk'
import { apexDomain } from '../audit-snapshot/domain.js'
import { brandMatchers, textMentions } from './checks/aiVisibility.js'
import { positioningFromPlaybook } from '../aeo/positioning.js'

const MODEL = 'claude-sonnet-4-6'
export const BUYER_PROMPT_COUNT = 8
const INTENTS = ['recommendation', 'problem', 'comparison']
const PROMPT_COLUMNS = 'id, prompt, intent, position, source, created_at'

function clean(v, max = 1500) {
  return String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max)
}

function listOf(v) {
  if (Array.isArray(v)) return v.map((x) => clean(typeof x === 'string' ? x : x?.name || x?.keyword || '', 200)).filter(Boolean)
  return String(v || '')
    .split(/\n|;|•/)
    .map((s) => clean(s.replace(/^[-*\d.)\s]+/, ''), 300))
    .filter(Boolean)
}

/** Everything prompt generation and detection need about the company. */
export async function loadBrandContext(supabase, companyId) {
  const [companyRes, profileRes, playbookRes, pillarsRes, promptsRes] = await Promise.all([
    supabase.from('companies').select('name').eq('id', companyId).maybeSingle(),
    supabase
      .from('company_profiles')
      .select('product_name, domain, seo_market')
      .eq('company_id', companyId)
      .maybeSingle(),
    supabase.from('aeo_playbook').select('brand_facts, icp').eq('company_id', companyId).maybeSingle(),
    supabase.from('aeo_pillars').select('name').eq('company_id', companyId).order('sort'),
    supabase
      .from('aeo_prompts')
      .select('prompt, intent_tier, business_value')
      .eq('company_id', companyId)
      .in('intent_tier', ['Problem', 'Buy'])
      .order('business_value', { ascending: false, nullsFirst: false })
      .limit(12),
  ])
  for (const r of [companyRes, profileRes, playbookRes, pillarsRes, promptsRes]) if (r.error) throw r.error
  const p = profileRes.data || {}
  const pos = positioningFromPlaybook({
    brandFacts: playbookRes.data?.brand_facts,
    icp: playbookRes.data?.icp,
    settings: p,
  })
  // The Playbook's own Problem/Buy prompts are the buyer's questions; Brand
  // Facts "problem" is the fallback when the prompt universe is still empty.
  const promptProblems = (promptsRes.data || []).map((row) => clean(row.prompt, 300)).filter(Boolean)
  return {
    companyName: clean(companyRes.data?.name, 120),
    productName: clean(p.product_name, 120),
    apex: apexDomain(p.domain || ''),
    primaryOffer: clean(pos.abstract),
    whatWeDo: clean(pos.abstract),
    targetSearcher: clean(pos.audience),
    buyerProblems: promptProblems.length ? promptProblems : listOf(pos.seoControls.buyerProblems),
    markets: clean(pos.seoControls.market, 200),
    outOfScope: clean(pos.seoControls.outOfScope, 600),
    competitors: pos.competitors,
    coreKeywords: [...new Set((pillarsRes.data || []).map((x) => clean(x?.name, 120)).filter(Boolean))],
  }
}

/** Names the brand goes by (for detection and the unbranded check). */
export function brandNames(ctx) {
  const names = [ctx.companyName, ctx.productName].filter(Boolean)
  // Drop legal suffixes so "The Night Ventures, LLC" also matches "The Night Ventures".
  for (const n of [...names]) {
    const stripped = n.replace(/,?\s+(inc|llc|ltd|corp|co)\.?$/i, '').trim()
    if (stripped && stripped !== n) names.push(stripped)
  }
  return [...new Set(names)]
}

export function brandPromptText(ctx) {
  const name = ctx.productName || ctx.companyName || ctx.apex
  return ctx.apex ? `What is ${name} (${ctx.apex}) and what do they offer?` : `What is ${name} and what do they offer?`
}

/**
 * Keep valid, unbranded, distinct prompts.
 * @param {Array<{ prompt?: string, intent?: string }>} raw
 * @param {{ matchers: RegExp[], names: string[] }} brand  brand matchers (names + domain) and raw names
 */
export function validatePrompts(raw, { matchers, names = [] }) {
  const lowerNames = names.map((n) => String(n).toLowerCase()).filter((n) => n.length >= 3)
  const seen = new Set()
  const out = []
  for (const r of Array.isArray(raw) ? raw : []) {
    const prompt = clean(r?.prompt, 300)
    if (prompt.length < 12) continue
    const lower = prompt.toLowerCase()
    if (textMentions(prompt, matchers) || lowerNames.some((n) => lower.includes(n))) continue
    const key = prompt.toLowerCase().replace(/[^a-z0-9 ]/g, '')
    if (seen.has(key)) continue
    seen.add(key)
    out.push({ prompt, intent: INTENTS.includes(r?.intent) ? r.intent : 'recommendation' })
  }
  return out.slice(0, BUYER_PROMPT_COUNT)
}

function generationPrompt(ctx) {
  const competitorNames = ctx.competitors.map((c) => clean(c?.name, 80)).filter(Boolean).slice(0, 8)
  return [
    'You write the questions a real buyer types into ChatGPT, Claude, Gemini or Perplexity before choosing a provider.',
    'They are used to measure whether a company shows up in AI answers, so they must be realistic, specific and unbranded.',
    '',
    `What the company sells: ${ctx.primaryOffer || ctx.whatWeDo || '(not set)'}`,
    `Who searches for it: ${ctx.targetSearcher || '(not set)'}`,
    `Problems the buyer has before buying: ${ctx.buyerProblems.join(' | ') || '(not set)'}`,
    `Core topics: ${ctx.coreKeywords.join(', ') || '(not set)'}`,
    `Competitors: ${competitorNames.join(', ') || '(none listed)'}`,
    `Market: ${ctx.markets || 'United States'}`,
    ctx.outOfScope ? `Out of scope (never ask about): ${ctx.outOfScope}` : '',
    '',
    `Write exactly ${BUYER_PROMPT_COUNT} questions:`,
    '- 3 "recommendation": asking which service, tool or firm to use (e.g. "What are the best services that…").',
    '- 3 "problem": asking how to solve the buyer\'s problem, where a provider would naturally be recommended.',
    `- 2 "comparison": asking for alternatives to, or comparisons with, a named competitor${competitorNames.length ? '' : ' or a category of provider'}.`,
    'Rules: first person or plain question form; 8–25 words; no company name or domain of the company being measured; no made-up facts; each question distinct.',
    '',
    'Return JSON only: {"prompts":[{"prompt":"…","intent":"recommendation|problem|comparison"}]}',
  ]
    .filter((l) => l !== '')
    .join('\n')
}

/** Ask Claude for buyer prompts. Throws on API failure. */
export async function generateBuyerPrompts(ctx) {
  const apiKey = process.env.ANTHROPIC_API_KEY
  if (!apiKey) throw new Error('ANTHROPIC_API_KEY is not configured')
  if (!ctx.primaryOffer && !ctx.whatWeDo) {
    throw new Error('Fill in Brand Facts → Offer in the AEO Playbook before generating AI prompts')
  }
  const anthropic = new Anthropic({ apiKey })
  const message = await anthropic.messages.create({
    model: MODEL,
    max_tokens: 1500,
    messages: [{ role: 'user', content: generationPrompt(ctx) }],
  })
  const text = (message.content || []).map((b) => (b.type === 'text' ? b.text : '')).join('')
  const json = text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1)
  let parsed
  try {
    parsed = JSON.parse(json)
  } catch {
    throw new Error('Prompt generation returned invalid JSON')
  }
  const names = brandNames(ctx)
  const matchers = brandMatchers({ names, apex: ctx.apex })
  const prompts = validatePrompts(parsed?.prompts, { matchers, names })
  if (prompts.length < 4) throw new Error(`Prompt generation returned only ${prompts.length} usable prompt(s)`)
  return prompts
}

export async function listPrompts(supabase, companyId) {
  const { data, error } = await supabase
    .from('audit_ai_prompts')
    .select(PROMPT_COLUMNS)
    .eq('company_id', companyId)
    .order('position', { ascending: true })
  if (error) throw error
  return data || []
}

/** Replace the company's prompt set with a fresh generated one. */
export async function regeneratePrompts(supabase, companyId, userId = null) {
  const ctx = await loadBrandContext(supabase, companyId)
  const buyer = await generateBuyerPrompts(ctx)
  const rows = [
    ...buyer.map((p, i) => ({ ...p, position: i, source: 'generated' })),
    { prompt: brandPromptText(ctx), intent: 'brand', position: 99, source: 'generated' },
  ].map((r) => ({ ...r, company_id: companyId, created_by: userId }))

  const { error: delError } = await supabase.from('audit_ai_prompts').delete().eq('company_id', companyId)
  if (delError) throw delError
  const { error } = await supabase.from('audit_ai_prompts').insert(rows)
  if (error) throw error
  return listPrompts(supabase, companyId)
}

/** The stored set, generating one on first use. */
export async function ensurePrompts(supabase, companyId) {
  const existing = await listPrompts(supabase, companyId)
  if (existing.some((p) => p.intent !== 'brand')) return { prompts: existing, generated: false }
  return { prompts: await regeneratePrompts(supabase, companyId), generated: true }
}

export async function removePrompt(supabase, companyId, promptId) {
  const { error } = await supabase.from('audit_ai_prompts').delete().eq('company_id', companyId).eq('id', promptId)
  if (error) throw error
  return listPrompts(supabase, companyId)
}
